import {SETTINGS} from './service-defaults.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const section=body=>`<section class="sec batch-section"><div class="wrap">${body}</div></section>`;
export function batchPages(root,path,settings,projects,catalog){
 const content=root.querySelector('.page-enter');if(!content)return;
 if(path==='/'){
  root.querySelector('[data-promotions-slider]')?.remove();
  for(const a of root.querySelectorAll('a[href]')){const href=a.getAttribute('href'),img=a.querySelector('.art img,img');if(!img)continue;let src;if(href==='/satin/apparel'||href==='/satin/apparel/')src='/satin/img/satin-shirt-logo.webp';if(href==='/satin/window-graphics'||href==='/satin/window-graphics/')src='/satin/img/window-vinyl.png';if(href==='/satin/shop'||href==='/satin/shop/')src='/satin/img/vehicle-wrap-tools.png';if(src){img.closest('picture')?.querySelectorAll('source').forEach(x=>x.remove());img.removeAttribute('srcset');img.src=src;}}
 }
 if(path==='/shop'||path==='/print-shop/large-format'){
  const links=path==='/shop'?[['Custom DTF Transfers','/satin/shop/dtf-transfers','satin-shirt'],['Social Media','/satin/social-media-services','service-social'],['Videography','/satin/videography','service-video']]:[['Poly Bag Lawn Sign','/satin/print-shop/large-format/poly-bag-lawn-sign','pr-yard-sign']];content.insertAdjacentHTML('beforeend',section(`<h2>More from Satin</h2><div class="grid g3">${links.map(([n,p,img])=>`<a class="card" href="${p}"><div class="art photo"><img src="/satin/img/${img}.${img==='satin-shirt'?'png':'jpg'}" alt="${n}"></div><h3>${n}</h3><span>Choose options ↗</span></a>`).join('')}</div>`));
 }
 if(path.startsWith('/window-graphics/')||path==='/window-tint/commercial'){
  const p=catalog.find(p=>p.path==='/satin'+path);const src=p?.images?.[0]||'/satin/img/window-vinyl.png';if(!root.querySelector('.batch-hero-photo')){const hero=root.querySelector('.hero .wrap,.hero');if(hero)hero.insertAdjacentHTML('beforeend',`<img class="batch-hero-photo" src="${esc(src)}" alt="${esc(p?.name||'Window film and glass graphics')}">`);}
  const notes=path.endsWith('full-window-graphics')?'Regular vinyl is an opaque printable film. Blackout film has grey adhesive to reduce show-through. Clear film keeps transparent areas of the design. Removable adhesive suits shorter campaigns; permanent adhesive provides a stronger bond. Removal depends on the glass condition and time installed.':path.endsWith('perforated-vinyl')?'Perforated vinyl combines printed advertising outside with a view through the unprinted openings from inside. Lighting changes affect one-way visibility; it does not guarantee privacy at night.':path.endsWith('window-decals')?'Single-colour calendered vinyl uses cut shapes and lettering. Full-colour digital print reproduces logos and images. Pricing starts at $15 per square foot. Confirm glass dimensions and installation conditions before production.':'Ceramic and regular window films reduce transmitted light. Select 20%, 35%, 60% or 70% VLT to compare darkness; higher VLT lets more visible light through.';content.insertAdjacentHTML('beforeend',section(`<h2>About the material</h2><p class="lede">${notes}</p>`));
 }
 if(path.startsWith('/wallpaper/'))content.insertAdjacentHTML('beforeend',section('<h2>Choose your wall finish</h2><div class="grid g2"><article class="card"><img src="/satin/img/wall-flat-matte-sample.webp" alt="Illustrative smooth matte wallpaper material sample" style="display:block;width:100%;height:180px;object-fit:cover;border-radius:12px" loading="lazy"><h3>Flat Matte</h3><p>A smooth, low-reflection finish for crisp artwork and photographs.</p></article><article class="card"><img src="/satin/img/wall-texture-sample.webp" alt="Illustrative linen-grain wallpaper material sample" style="display:block;width:100%;height:180px;object-fit:cover;border-radius:12px" loading="lazy"><h3>Texture</h3><p>A tactile surface that adds visual depth. Ask for a physical sample to confirm the finish.</p></article></div><p>Images illustrate the finish types. Ask for a physical sample to confirm the exact texture and colour. Wallpaper is made to your wall measurements. Surface preparation, colour approval and panel alignment affect the final result.</p>'));
 if(path==='/shop/vehicle-wrap-designs')import('/wrap-design-ui.mjs').then(m=>m.upgradeDesignCards(root)).catch(()=>{});
 if(path==='/shop/vehicle-wrap-designs'){const filters=root.querySelector('[data-filters]'),grid=root.querySelector('[data-designs]');if(filters&&grid){const layout=document.createElement('div');layout.className='shop-filter-layout';grid.before(layout);const sidebar=document.createElement('aside');sidebar.className='shop-filter-list';const cards=[...grid.children],keys=[['style','Style'],['ind','Industry'],['col','Colour']];sidebar.innerHTML='<h3>Filter designs</h3><input class="inp" type="search" data-design-search placeholder="Search designs" style="width:100%;margin-bottom:14px">'+keys.map(([key,label])=>`<fieldset><legend>${label}</legend>${[...new Set(cards.map(c=>c.dataset[key]))].map(value=>`<label><input type="checkbox" data-filter-key="${key}" value="${esc(value)}">${esc(value)} <span class="small" style="color:#888">(${cards.filter(c=>c.dataset[key]===value).length})</span></label>`).join('')}</fieldset>`).join('')+'<button type="button" class="btn ghost sm" data-clear-filters>Clear filters</button>';sidebar.addEventListener('input',()=>sidebar.onchange());sidebar.addEventListener('click',e=>{if(e.target.closest('[data-clear-filters]')){sidebar.querySelectorAll('input[type=checkbox]').forEach(x=>x.checked=false);sidebar.querySelector('[data-design-search]').value='';sidebar.onchange();}});layout.append(sidebar,grid);filters.remove();sidebar.onchange=()=>{let count=0;cards.forEach(c=>{const q=(sidebar.querySelector('[data-design-search]')?.value||'').toLowerCase();c.hidden=!(keys.every(([key])=>{const selected=[...sidebar.querySelectorAll(`[data-filter-key="${key}"]:checked`)].map(x=>x.value);return !selected.length||selected.includes(c.dataset[key]);})&&c.textContent.toLowerCase().includes(q));if(!c.hidden)count++;});root.querySelector('[data-count]').textContent=count;root.querySelector('[data-empty]').hidden=!!count;};}}
 if(path==='/website-design')content.insertAdjacentHTML('beforeend',section('<h2>Website examples</h2><p>Hosting and domain registration are charged separately from design.</p><div class="grid g3">'+['web-1','web-2','web-3'].map(n=>`<article class="card"><div class="art photo"><img src="/satin/img/${n}.jpg" alt="Website design example"></div><p>Design style example · project scope is tailored to your business.</p></article>`).join('')+'</div>'));
 if(path==='/videography')videographyPage(root,content,settings);
 if(path==='/shop/design-services')content.insertAdjacentHTML('beforeend',section('<div class="split"><div><h2>Design for your whole brand</h2><p>Vehicle wrap design $250 · window graphics $150 · print artwork $100 · wallpaper $150 · apparel $30.</p><p>Share supporting artwork, references or a sample with your exact quote request. For a standard service, select it above and purchase through checkout.</p></div><div class="art photo"><img src="/satin/img/web-wrap.jpg" alt="Brand and vehicle wrap design"></div></div>'));
 if(path==='/shop/vehicle-templates'&&!root.querySelector('[data-template-price-note]')){const host=root.querySelector('[data-vehicle-catalog]');(host||content).insertAdjacentHTML(host?'beforebegin':'beforeend',`<p class="lede" data-template-price-note>Each vector template is $25 CAD. Choose your vehicle to see the preview; the download link is released after confirmed payment. Can't find your vehicle? Request it and our team will contact you.</p>`);}
 if(path==='/shop/vehicle-wrap-prints'){const hero=root.querySelector('.hero .wrap,.hero');if(hero&&!root.querySelector('.batch-hero-photo'))hero.insertAdjacentHTML('beforeend','<img class="batch-hero-photo" src="/satin/img/job-greenlife-van.jpg" alt="Completed commercial vehicle wrap">');}
}

