const vidIcon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${VID_ICONS[k]||''}</svg>`;
const boldZeus=s=>esc(s).replace(/Zeus Frames/g,'<b>Zeus Frames</b>');
const zeusLogo=(cls='',deco=false)=>`<span class="zeus-logo ${cls}"${deco?' aria-hidden="true"':''}><img src="/satin/img/zeus-frames-logo-white.svg" alt="${deco?'':'Zeus Frames logo'}" width="248" height="378" loading="lazy" decoding="async"></span>`;
function videographyPage(root,content,settings){
 const lang=(document.documentElement.lang||'en').slice(0,2).toLowerCase(),T=VID_I18N[lang]||VID_I18N.en,E=VID_I18N.en;
 const v=settings.videoPartner||{plans:[]},def=SETTINGS.videoPartner||{};
 content.classList.add('vidp');
 const hero=root.querySelector('.service-hero');
 if(hero){
  hero.classList.add('vid-hero');
  hero.querySelector('.zeus-badge')?.remove();
  if(!hero.querySelector('.zeus-partner')){
   const anchor=hero.querySelector('.service-actions')||hero.querySelector('.lede');
   anchor?.insertAdjacentHTML('afterend',`<a class="zeus-partner" data-cms-skip href="${ZEUS_URL}" target="_blank" rel="noopener" aria-label="${esc(E.partner+' Zeus Frames — '+T.visit+' ('+T.newTab+')')}">${zeusLogo()}<span class="zeus-partner-txt"><small>${esc(T.partner)}</small><b>Zeus Frames</b><span>${esc(T.partnerSub)}</span></span><span class="zeus-partner-go" aria-hidden="true">↗</span></a>`);
  }
 }
 /* services: right after the hero */
 if(hero&&!root.querySelector('.vid-services')){
  hero.insertAdjacentHTML('afterend',`<section class="sec vid-services" data-cms-section="svid-services" data-cms-skip><div class="wrap"><div class="sec-head"><span class="eyebrow">${esc(T.svcEyebrow)}</span><h2 class="d2">${esc(T.svcTitle)}</h2><p class="lede">${T.svcLede}</p></div><div class="vid-svc-grid">${T.svc.map(([ic,h,p])=>`<article class="vid-svc"><span class="vid-svc-ic">${vidIcon(ic)}</span><h3>${esc(h)}</h3><p>${esc(p)}</p></article>`).join('')}</div></div></section>`);
 }
 /* process: the original "What is included" section (01 · 02 · 03) */
 const proc=root.querySelector('.service-features')?.closest('section');
 if(proc)proc.classList.add('vid-process');
 /* price plans (existing Zeus Frames data, unchanged) */
 if(!root.querySelector('.zeus-plans')&&v.plans?.length){
  const cats=[...new Set(v.plans.map(p=>p.category||'Videography'))];
  const title=(T.title&&v.title===def.title)?T.title:boldZeus(v.title),text=(T.text&&v.text===def.text)?T.text:boldZeus(v.text);
  const html=`<div class="zeus-head"><div><span class="eyebrow">${esc(T.plansEyebrow)}</span><h2 class="d2 zeus-title">${title}</h2><p class="lede">${text}</p></div><a class="zeus-card" href="${ZEUS_URL}" target="_blank" rel="noopener" data-cms-skip>${zeusLogo('lg')}<span><small>${esc(T.partnerLine)}</small><b>Zeus Frames</b><em>${esc(T.visit)} ↗</em></span></a></div><div class="zeus-tabs" role="tablist" aria-label="${esc(T.plansEyebrow)}">${cats.map((c,i)=>`<button type="button" role="tab" aria-selected="${i===0}" data-zeus-tab="${esc(c)}">${esc(T.cats[c]||c)}</button>`).join('')}</div>${cats.map((c,i)=>{const list=v.plans.filter(p=>(p.category||'Videography')===c);return `<div class="zeus-plans n${list.length}" role="tabpanel" data-zeus-panel="${esc(c)}" ${i?'hidden':''}>${list.map((p,j)=>`<article class="card zeus-plan ${j===1?'pop':''}">${j===1?`<span class="zeus-pop">${esc(T.popular)}</span>`:''}<h3 dir="auto">${esc(p.name)}</h3><b class="plan-price" dir="auto">${esc(p.price)}</b><ul>${String(p.detail).split(' · ').map(x=>`<li dir="auto">${esc(x)}</li>`).join('')}</ul><button type="button" class="btn ${j===1?'':'ghost'}" data-service-plan="${esc(p.name)}">${esc(T.choose)}</button></article>`).join('')}</div>`;}).join('')}<p class="small zeus-foot">${esc(T.partnerLine)} <a href="${ZEUS_URL}" target="_blank" rel="noopener"><b>Zeus Frames</b></a> · <a href="https://www.instagram.com/zeusframes.inc/" target="_blank" rel="noopener">${esc(T.insta)}</a></p>`;
  const target=root.querySelector('#packages');
  if(target){target.classList.add('vid-plans');target.innerHTML=`<div class="wrap" data-cms-skip>${html}</div>`;}
  else content.insertAdjacentHTML('beforeend',`<section class="sec alt vid-plans" id="packages" data-cms-section="svid-plans" data-cms-skip><div class="wrap">${html}</div></section>`);
  const sel=root.querySelector('form[data-service-request] [name=plan]');if(sel)sel.innerHTML=`<option value="">Custom selection</option>`+v.plans.map(p=>`<option>${esc(p.name)}</option>`).join('');
  root.querySelectorAll('[data-zeus-tab]').forEach(t=>t.onclick=()=>{root.querySelectorAll('[data-zeus-tab]').forEach(x=>x.setAttribute('aria-selected',String(x===t)));root.querySelectorAll('[data-zeus-panel]').forEach(pn=>pn.hidden=pn.dataset.zeusPanel!==t.dataset.zeusTab);});
  root.querySelectorAll('.zeus-plans [data-service-plan]').forEach(b=>b.onclick=()=>{const f=root.querySelector('form[data-service-request]');if(!f)return;f.querySelector('[name=plan]').value=b.dataset.servicePlan;f.scrollIntoView({behavior:'smooth',block:'start'});});
 }
 /* FAQ: two partner answers appended to the existing list */
 const faq=root.querySelector('.faq');
 if(faq&&!faq.querySelector('[data-vid-faq]')){faq.closest('section')?.classList.add('vid-faq');faq.insertAdjacentHTML('beforeend',T.faq.map(([q,a])=>`<details data-vid-faq data-cms-skip><summary>${esc(q)}</summary><div>${a}</div></details>`).join(''));}
 /* closing call to action */
 if(!root.querySelector('.vid-cta')){
  const last=faq?.closest('section')||content.lastElementChild;
  const html=`<section class="sec tight vid-cta-sec" data-cms-section="svid-cta" data-cms-skip><div class="wrap"><div class="cta vid-cta"><div><h2 class="d2">${esc(T.ctaTitle)}</h2><p>${T.ctaText}</p></div><div class="acts"><a class="btn" href="#configure">${esc(T.ctaQuote)}</a><a class="btn ghost" href="#packages">${esc(T.ctaPlans)}</a></div></div></div></section>`;
  if(last)last.insertAdjacentHTML('afterend',html);else content.insertAdjacentHTML('beforeend',html);
 }
}
